WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, attr_key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) li AS attr_key, attr_value), exploded AS (SELECT id, created_at, attr_key, attr_value, EXPLODE_OUTER(coupon_codes) AS tag FROM flattened), cleaned AS (SELECT *, LENGTH(attr_key) AS attr_key_length, CASE WHEN attr_key IN ('weight_kg', 'utm_source') THEN 'Core' ELSE 'Other' END AS attr_key_group FROM exploded WHERE tag IS NOT NULL AND created_at > TO_DATE('2025-03-01')), enriched AS (SELECT *, MAX(attr_key_length) OVER (PARTITION BY attr_key ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS attr_key_length_max_2h, AVG(attr_key_length) OVER (PARTITION BY attr_key) AS attr_key_avg_attr_key_length FROM cleaned), cleaned_carts AS (SELECT *, HOUR(created_at) AS created_at_hour, COALESCE(attr_key, 'DIRECT') AS attr_key_filled FROM enriched WHERE created_at >= DATE '2025-03-01') SELECT id, created_at, attr_key, attr_value, tag, attr_key_length, attr_key_length_max_2h, attr_key_avg_attr_key_length, created_at_hour, CASE WHEN tag RLIKE '^(VIP|WELCOME5)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS tag_zone FROM cleaned_carts ORDER BY created_at_hour
